#!/usr/bin/env python3
"""Safely update the reviewed Dottore Archive localization text.

Usage:
  python update_localization.py /path/to/testing-yugzie

The script changes only the 14 reviewed keys in each locale file.
It stops without writing if an expected original string is missing or duplicated.
"""
from pathlib import Path
import sys

CHANGES = {'lang/en.js': {'timelineChildhoodText': ('In a memory of Zandik’s early years, people from his hometown pursue the young boy with clubs and pitchforks, forcing him to flee. The available canon does not state why they were hostile to him, so the archive does not supply a reason.', 'In a memory of his early years, Zandik is chased from his hometown by residents carrying clubs and pitchforks. The reason for their hostility is never established in the available canon.'), 'timelineAcademiyaText': ('Early field records connect Zandik with the Akademiya, expeditions, and the study of ancient mechanisms. These documents show his interest in technologies that exceeded ordinary academic practice.', 'Early records connect Zandik with Akademiya expeditions and the study of ancient mechanisms.'), 'timelineTatarasunaText': ('Several centuries before the main story, Dottore operates in Inazuma under the identity of the mechanic Escher. The Tatarasuna incident becomes part of Kabukimono’s history and is later revealed to the Traveler through recovered memories.', 'Centuries before the Traveler’s journey, Dottore operates in Inazuma under the alias Escher, a mechanic involved in the events at Tatarasuna.'), 'timelineSumeruText': ('In Sumeru’s main story, Dottore cooperates with the Akademiya sages in the project to transform Scaramouche into an artificial god. After the project fails, he personally negotiates with Nahida: the bargain leaves him with both Gnoses, while her condition forces him to destroy his remaining Segments.', 'In Sumeru, Dottore works with the Akademiya sages to turn Scaramouche into an artificial god. After the project is stopped, he negotiates with Nahida over the Gnoses and the destruction of his remaining Segments.'), 'timelinePuranaText': ('In Luna VII, Segment 35 carries his experiment into its final stage by binding his existence to Irminsul. The challenge description explicitly states that he casts off the constraints of corporeal form and merges with Irminsul. In the final confrontation, his manifestation perishes together with the burning Irminsul. For the archive, this is the current confirmed endpoint of Segment 35 – without speculating about a possible return.', 'In Luna VII, Segment 35 advances his experiment by binding his existence to Irminsul. The challenge description states that he casts off the limits of corporeal form and merges with the tree. During the final confrontation, his visible manifestation is lost as Irminsul burns. This establishes the loss of that manifestation, not the erasure of every record or part of Dottore’s identity.'), 'timelineNodKraiText': ('Later, Dottore intervenes in the events of Nod-Krai surrounding Columbina and the power of the moons. He creates his own system, harnesses lunar forces, and enters direct conflict with the Traveler and their allies.', 'In Nod-Krai, Dottore pursues an experiment involving lunar power and confronts the Traveler and their allies. His lunar manifestation is defeated, but he later confirms that he obtained the information he sought from the process. The defeat does not establish the fate of every part of his identity.'), 'timelineRecruitText': ('After his break with the Akademiya, Zandik enters the Fatui. The artifact \\"Wise Doctor’s Pinion\\" connects his path with Pierro, who offers him a place where his research would no longer be constrained by his former limits.', 'After his expulsion from the Akademiya, Zandik joins the Fatui. The artifact \\"Wise Doctor’s Pinion\\" connects this transition with Pierro, who offers him an environment where his research can continue beyond the restrictions of academic life.'), 'timeline.p.1': ('In a memory of his early years, the young Zandik is chased from his home village by residents carrying clubs and pitchforks. The available canon does not state why they were hostile, so the archive does not fill in the reason.', 'In a memory of his early years, Zandik is shown fleeing as residents of his hometown pursue him with clubs and pitchforks. The scene establishes their hostility and his flight, but gives no reason for it.'), 'timeline.p.2': ('Early field records connect Zandik with the Akademiya, expeditions, and the study of ancient mechanisms. These documents show an interest in technology that exceeded ordinary academic practice.', 'Early field records link Zandik to Akademiya expeditions and the study of ancient mechanisms. They document his interest in technologies beyond conventional academic practice.'), 'timeline.p.3': ('After his break with the Akademiya, Zandik enters the Fatui. \\"Wise Doctor’s Pinion\\" connects this transition with Pierro, who offers an environment and resources where his research is no longer constrained by his former academic framework. The artifact also refers to rumors of heresy surrounding him, but does not establish that those rumors caused the earlier hostility in his hometown.', 'After his expulsion from the Akademiya, Zandik joins the Fatui. \\"Wise Doctor’s Pinion\\" links this transition to Pierro, who offers resources and an environment for research beyond the restrictions of academic life. The artifact mentions rumors of heresy around Zandik, but does not establish that they caused the hostility in his hometown.'), 'timeline.p.4': ('Several centuries before the main story, Dottore operates in Inazuma under the identity of the mechanic Escher. The Tatarasuna incident becomes part of Kabukimono’s history and is later revealed to the Traveler through memories.', 'Centuries before the Traveler’s journey, Dottore operates in Inazuma under the alias Escher. While posing as a mechanic at Tatarasuna, he sabotages the forge, kills Niwa, and uses Niwa’s heart to convince Kabukimono that his friend had betrayed him. These events become a defining part of Kabukimono’s history and are later revealed to the Traveler through recovered memories.'), 'timeline.p.9': ('During Sumeru’s main story, Dottore works with the Akademiya sages on the project to turn Scaramouche into an artificial god. After the project fails, he personally negotiates with Nahida: the bargain gives him both Gnoses, while her price requires him to destroy his remaining Segments.', 'During Sumeru’s main story, Dottore works with the Akademiya sages to turn Scaramouche into an artificial god. After the project is stopped, he negotiates with Nahida over both Gnoses. He obtains the Electro Gnosis on the condition that he destroy his remaining Segments, while he retains the Dendro Gnosis after providing information about the false sky.'), 'timeline.p.12': ('Under his arrangement with Dottore, Pantalone places the Doctor’s final data backup into the Ley Lines. Segment 35 then casts off the constraints of physical form and merges with Irminsul, continuing the experiment from within. His visible manifestation disappears when Irminsul burns, while the records preserve digitized memories. Canon confirms those data and the loss of the manifestation, but by itself proves neither permanent annihilation nor a return.', 'Under his arrangement with Dottore, Pantalone places the Doctor’s final data backup into the Ley Lines. He also explains that the remainder of Dottore’s soul was split, with one half sent to Nod-Krai and the other stored in a Northland Bank vault. Segment 35 then casts off the limits of physical form and merges with Irminsul, continuing the experiment from within. His visible manifestation is lost when Irminsul burns. This establishes the fate of that manifestation, but not the erasure of every stored record or separated part of Dottore’s identity.'), 'sourcePurana': ('Source · Luna VII + Dottore challenge', 'Source · \\"Truth Amongst the Pages of Purana\\" + challenge description')}, 'lang/ru.js': {'timelineChildhoodText': ('В воспоминании о ранних годах маленького Зандика жители его родной деревни преследуют его с дубинами и вилами, вынуждая бежать. Причина такой враждебности в доступном каноне не раскрывается, поэтому архив её не предполагает.', 'В воспоминании о ранних годах Зандика жители его родной деревни преследуют его с дубинами и вилами. Причина их враждебности в доступном каноне не раскрывается.'), 'timelineAcademiyaText': ('Ранние полевые записи связывают Зандика с Академией, экспедициями и исследованием древних механизмов. Эти документы показывают его интерес к технологиям, выходившим за пределы обычной академической практики.', 'Ранние записи связывают Зандика с экспедициями Академии и исследованием древних механизмов.'), 'timelineTatarasunaText': ('За несколько столетий до основной истории Дотторе действует в Инадзуме под именем механика Эшера. События Татарасуны становятся частью истории Кабукимоно и позднее раскрываются Путешественнику через воспоминания.', 'За несколько столетий до путешествия главного героя Дотторе действует в Инадзуме под именем Эшер — механика, связанного с событиями Татарасуны.'), 'timelineSumeruText': ('В основной истории Сумеру Дотторе сотрудничает с мудрецами Академии в проекте превращения Скарамуччи в искусственного бога. После поражения проекта он лично ведёт переговоры с Нахидой: в результате сделки получает оба Сердца Бога, а по её условию уничтожает остальные свои Сегменты.', 'В Сумеру Дотторе сотрудничает с мудрецами Академии, чтобы превратить Скарамуччу в искусственного бога. После срыва проекта он ведёт переговоры с Нахидой об обоих Сердцах Бога и уничтожении оставшихся Сегментов.'), 'timelinePuranaText': ('В Luna VII 35-й Сегмент доводит эксперимент до финальной стадии, связав своё существование с Ирминсулем. Описание испытания прямо указывает, что он отбросил ограничения физической формы и слился с Ирминсулем. В финале противостояния его проявление погибает вместе с горящим Ирминсулем. Для архива это текущая подтверждённая конечная точка 35-го Сегмента – без предположений о возможном возвращении.', 'В Luna VII 35-й Сегмент продвигает эксперимент, связывая своё существование с Ирминсулем. В описании испытания говорится, что он отбрасывает ограничения физической формы и сливается с деревом. Во время финального противостояния его видимое проявление теряется в пламени горящего Ирминсуля. Это подтверждает потерю данного проявления, но не доказывает исчезновение всех записей или частей личности Дотторе.'), 'timelineNodKraiText': ('Позднее Дотторе вмешивается в события Нод-Края, связанные с Коломбиной и силой лун. Он создаёт собственную систему, использует лунные силы и выходит на прямое противостояние с Путешественником и их союзниками.', 'В Нод-Крае Дотторе проводит эксперимент, связанный с лунной силой, и вступает в противостояние с Путешественником и их союзниками. Его лунное проявление терпит поражение, однако позднее он подтверждает, что получил искомые сведения. Это поражение не устанавливает судьбу всех частей его личности.'), 'timelineRecruitText': ('После разрыва с Академией Зандик оказывается среди Фатуи. В описании артефакта \\"Перо мудрого лекаря\\" его путь связан с Пьеро, который предлагает ему место, где исследования не будут ограничены прежними рамками.', 'После изгнания из Академии Зандик вступает в Фатуи. Описание артефакта \\"Перо мудрого лекаря\\" связывает этот переход с Пьеро, который предлагает ему условия для исследований за пределами прежних академических ограничений.'), 'timeline.p.1': ('В воспоминании о ранних годах маленького Зандика жители его родной деревни преследуют его с дубинами и вилами, вынуждая бежать. Причина такой враждебности в доступном каноне не раскрывается, поэтому архив её не предполагает.', 'В воспоминании о ранних годах Зандик убегает от жителей родной деревни, преследующих его с дубинами и вилами. Сцена показывает их враждебность и его бегство, но не объясняет причину конфликта.'), 'timeline.p.2': ('Ранние полевые записи связывают Зандика с Академией, экспедициями и исследованием древних механизмов. Эти документы показывают его интерес к технологиям, выходившим за пределы обычной академической практики.', 'Ранние полевые записи связывают Зандика с экспедициями Академии и исследованием древних механизмов. Они документируют его интерес к технологиям за пределами привычной академической практики.'), 'timeline.p.3': ('После разрыва с Академией Зандик оказывается среди Фатуи. \\"Перо мудрого лекаря\\" связывает этот переход с Пьеро, который предлагает ему среду и ресурсы, где исследования больше не ограничены прежними академическими рамками. В описании артефакта также упоминаются слухи о ереси вокруг Зандика, но не утверждается, что именно они стали причиной враждебности жителей его родной деревни.', 'После изгнания из Академии Зандик вступает в Фатуи. \\"Перо мудрого лекаря\\" связывает этот переход с Пьеро, который предлагает ему ресурсы и условия для исследований за пределами прежних академических ограничений. В описании артефакта упоминаются слухи о ереси вокруг Зандика, но не утверждается, что именно они стали причиной враждебности жителей его родной деревни.'), 'timeline.p.4': ('За несколько столетий до основной истории Дотторе действует в Инадзуме под именем механика Эшера. События Татарасуны становятся частью истории Кабукимоно и позднее раскрываются Путешественнику через воспоминания.', 'За несколько столетий до путешествия главного героя Дотторе действует в Инадзуме под именем Эшер. Выдавая себя за механика на Татарасуне, он саботирует кузницу, убивает Ниву и использует его сердце, чтобы убедить Кабукимоно, будто друг предал его. Эти события становятся важной частью истории Кабукимоно и позднее раскрываются Путешественнику через восстановленные воспоминания.'), 'timeline.p.9': ('В основной истории Сумеру Дотторе сотрудничает с мудрецами Академии в проекте превращения Скарамуччи в искусственного бога. После поражения проекта он лично ведёт переговоры с Нахидой: в результате сделки получает оба Сердца Бога, а по её условию уничтожает остальные свои Сегменты.', 'В основной истории Сумеру Дотторе сотрудничает с мудрецами Академии, чтобы превратить Скарамуччу в искусственного бога. После срыва проекта он договаривается с Нахидой об обоих Сердцах Бога. Электро Сердце Бога он получает при условии уничтожить оставшиеся Сегменты, а Дендро Сердце Бога сохраняет, предоставив сведения о ложном небе.'), 'timeline.p.12': ('По договорённости с Дотторе Панталоне помещает его последнюю резервную копию данных в Линии артерий. 35-й затем отбрасывает ограничения физического тела и сливается с Ирминсулем, продолжая эксперимент изнутри. Его видимое проявление исчезает при сожжении Ирминсуля, а записи сохраняют оцифрованные воспоминания. Канон подтверждает эти данные и потерю проявления, но сам по себе не доказывает ни окончательное уничтожение личности, ни её возвращение.', 'По договорённости с Дотторе Панталоне помещает его последнюю резервную копию данных в Линии артерий. Он также объясняет, что остаток души Дотторе был разделён: одна часть отправлена в Нод-Край, а другая помещена в хранилище Северного банка. Затем 35-й Сегмент отбрасывает ограничения физического тела и сливается с Ирминсулем, продолжая эксперимент изнутри. Его видимое проявление теряется при сожжении Ирминсуля. Это устанавливает судьбу данного проявления, но не доказывает исчезновение всех сохранённых данных или отделённых частей личности Дотторе.'), 'sourcePurana': ('Источник · Luna VII + испытание Dottore', 'Источник · \\"Истина среди страниц Пураны\\" + описание испытания')}}

def main():
    if len(sys.argv) != 2:
        raise SystemExit("Usage: python update_localization.py /path/to/testing-yugzie")
    root = Path(sys.argv[1])
    changed_files = []
    for relative_path, mapping in CHANGES.items():
        path = root / relative_path
        if not path.is_file():
            raise SystemExit(f"Missing file: {path}")
        content = path.read_text(encoding="utf-8")
        updated = content
        for key, (old_text, new_text) in mapping.items():
            old = f'"{key}": "{old_text}"'
            new = f'"{key}": "{new_text}"'
            count = updated.count(old)
            if count != 1:
                raise SystemExit(
                    f"Stopped safely: {relative_path} key {key!r}: expected exactly one old value, found {count}."
                )
            updated = updated.replace(old, new, 1)
        changed_files.append((path, updated))
    # All replacements validated before writing either file.
    for path, updated in changed_files:
        path.write_text(updated, encoding="utf-8", newline="")
        print(f"Updated: {path}")
    print("Done. Review the changes and test the site before uploading/committing.")

if __name__ == "__main__":
    main()
